#include <stdio.h>
#include <stdlib.h>

typedef __int128_t int128;

typedef struct {
    int128 y1;
    int128 y2;
} Line;

int compare_lines(const void *a, const void *b) {
    const Line *la = (const Line *)a;
    const Line *lb = (const Line *)b;
    if (la->y1 < lb->y1) return -1;
    if (la->y1 > lb->y1) return 1;
    if (la->y2 > lb->y2) return -1;
    if (la->y2 < lb->y2) return 1;
    return 0;
}

int compare_int128(const void *a, const void *b) {
    int128 va = *(const int128 *)a;
    int128 vb = *(const int128 *)b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

int bit_size;
int *bit;

void bit_add(int idx, int val) {
    for (; idx <= bit_size; idx += idx & -idx) {
        bit[idx] += val;
    }
}

int bit_query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
}

int lower_bound(int128 *arr, int n, int128 val) {
    int l = 0, r = n - 1;
    int ans = n;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] >= val) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

int main() {
    int n;
    long long x1_in, x2_in;
    if (scanf("%d %lld %lld", &n, &x1_in, &x2_in) != 3) return 0;

    int128 x1 = x1_in;
    int128 x2 = x2_in;

    Line *lines = (Line *)malloc(n * sizeof(Line));
    int128 *y2_vals = (int128 *)malloc(n * sizeof(int128));

    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        int128 a128 = a;
        int128 b128 = b;
        lines[i].y1 = a128 * x1 + b128;
        lines[i].y2 = a128 * x2 + b128;
        y2_vals[i] = lines[i].y2;
    }

    qsort(y2_vals, n, sizeof(int128), compare_int128);

    int unique_y2 = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || y2_vals[i] != y2_vals[i - 1]) {
            y2_vals[unique_y2++] = y2_vals[i];
        }
    }

    qsort(lines, n, sizeof(Line), compare_lines);

    bit_size = unique_y2;
    bit = (int *)calloc(bit_size + 1, sizeof(int));

    long long non_intersecting = 0;

    for (int i = 0; i < n; i++) {
        int rk = lower_bound(y2_vals, unique_y2, lines[i].y2);
        // rk is 0-indexed, corresponding to 1-based index rk + 1.
        // Elements strictly smaller than lines[i].y2 have rank <= rk - 1 (1-based: <= rk)
        non_intersecting += bit_query(rk);
        bit_add(rk + 1, 1);
    }

    long long total_pairs = (long long)n * (n - 1) / 2;
    long long ans = total_pairs - non_intersecting;

    printf("%lld\n", ans);

    free(lines);
    free(y2_vals);
    free(bit);

    return 0;
}
